from concurrent.futures import ThreadPoolExecutor

import pytest


def square(x: int) -> int:
    return x * x


def sum_squares(xs: list[int], *, workers: int = 4) -> int:
    """Return the sum of square(x) for every x in xs.

    The squares are computed on a ThreadPoolExecutor with `workers` threads.
    The result does not depend on `workers`.
    Raises ValueError if workers < 1.
    """
    if workers < 1:
        raise ValueError("workers must be >= 1")
    with ThreadPoolExecutor(max_workers=workers) as pool:
        return sum(pool.map(square, xs))


def test_square() -> None:
    assert square(-3) == 9
    assert square(0) == 0


@pytest.mark.parametrize("workers", [1, 2, 3, 4, 8, 16])
def test_sum_squares_same_at_every_worker_count(workers: int) -> None:
    xs = list(range(-50, 1000))
    expected = sum(x * x for x in xs)
    assert sum_squares(xs, workers=workers) == expected


def test_sum_squares_empty() -> None:
    assert sum_squares([]) == 0


def test_sum_squares_single_element() -> None:
    assert sum_squares([7]) == 49


def test_sum_squares_default_workers() -> None:
    xs = [1, 2, 3]
    assert sum_squares(xs) == 14


def test_sum_squares_rejects_nonpositive_workers() -> None:
    with pytest.raises(ValueError):
        sum_squares([1, 2], workers=0)
